const input = $input.first().json;
const body = input.body || input;

if (!body.event_id || !body.event_type || !body.decision) {
  return [{ json: { valid: false, reason: 'Missing required event_id, event_type, or decision' } }];
}

const staticData = $getWorkflowStaticData('global');
staticData.seenEvents = staticData.seenEvents || [];
if (staticData.seenEvents.includes(body.event_id)) {
  return [{ json: { valid: false, duplicate: true, event_id: body.event_id, reason: 'Duplicate event_id ignored' } }];
}
staticData.seenEvents.push(body.event_id);
if (staticData.seenEvents.length > 500) {
  staticData.seenEvents = staticData.seenEvents.slice(-500);
}

const isIncident = body.event_type === 'VOICE_VERIFICATION_COMPLETED' && ['REJECTED', 'REVIEW'].includes(body.decision);
const severity = body.decision === 'REJECTED' || body.voice_authenticity === 'SUSPICIOUS' ? 'CRITICAL' : 'MEDIUM';

return [{
  json: {
    valid: true,
    duplicate: false,
    isIncident,
    severity,
    event_id: body.event_id,
    event_type: body.event_type,
    session_id: body.session_id,
    industry: body.industry,
    action: body.action,
    decision: body.decision,
    voice_authenticity: body.voice_authenticity,
    speaker_match: body.speaker_match,
    challenge_valid: body.challenge_valid,
    risk_level: body.risk_level,
    timestamp: body.timestamp
  }
}];

const ev = $input.first().json;
const notification = {
  alert_title: `[${ev.severity}] VoiceSuraksha Security Incident (${ev.industry})`,
  event_id: ev.event_id,
  session_id: ev.session_id,
  industry: ev.industry,
  action: ev.action,
  decision: ev.decision,
  voice_authenticity: ev.voice_authenticity,
  speaker_match: ev.speaker_match,
  challenge_valid: ev.challenge_valid,
  summary: `Operation ${ev.action} in ${ev.industry} resulted in ${ev.decision}. Authenticity=${ev.voice_authenticity}, SpeakerMatch=${ev.speaker_match}.`,
  notified_at: new Date().toISOString(),
  channel: 'testable_notification_log'
};
return [{ json: { status: 'incident_notified', notification } }];
